27	use crate::sequences::{
28	    ActiveSequencesMultiWorker, ReplicaWorkerPolicy, SequenceError, SequenceRequest,
29	};
30	use crate::services::common::replica_sync::{
31	    ReplicaSyncConfig, ScopedReplicaEvent, ScopedSequencePublisher, setup_scoped_replica_sync,
32	};
33	use crate::services::indexer::backend::Indexer;
34	use crate::services::indexer::recovery;
35	use crate::services::indexer::registry::WorkerRegistry;
36	use crate::services::overlap::MooncakeOverlapSummary;
37	use crate::tracking_hash::{TrackingHashContext, TrackingHashScope};
38	
39	use super::catalog::WorkerCatalog;
40	use super::error::SelectionError;
41	use super::input::{PromptRequest, TrackingHashInput};
42	use super::pending::{PendingSelection, SelectionCache, SelectionCacheConfig};
43	use super::types::{
44	    ModelLoadResponse, OverlapScoresRequest, OverlapScoresResponse, PotentialLoadsRequest,
45	    ReadyResponse, ReservationRequest, ReservationResponse, SelectAndReserveRequest, SelectRequest,
46	    SelectResponse, SelectionWorkerConfig, WorkerCatalogRecord, WorkerLifecycle,
47	    WorkerPatchRequest, WorkerRequest,
48	};
49	use crate::WorkerSelectionPolicyFactory;
50	use crate::WorkerType;
51	
52	type SelectionScheduler = LocalScheduler<
53	    ScopedSequencePublisher,
54	    SelectionWorkerConfig,
55	    WorkerSelectionPolicy,
56	    TieredOverlapRefresher<Indexer>,
57	>;
58	
59	struct SelectionEntry {
60	    key: RoutingPartitionId,
61	    block_size: u32,
62	    is_eagle: bool,
63	    indexer: Indexer,
64	    workers_tx: watch::Sender<HashMap<WorkerId, SelectionWorkerConfig>>,
65	    scheduler: SelectionScheduler,
66	    replica_tx: Option<mpsc::Sender<ActiveSequenceEvent>>,
67	}
68	
69	struct PreparedSelectionInputs {
70	    block_hashes: Vec<LocalBlockHash>,
71	    sequence_hashes: Vec<SequenceHash>,
72	    isl_tokens: usize,
73	    overlap: OverlapSignals,
74	}
75	
76	struct SelectionOperation {
77	    key: RoutingPartitionId,
78	    selection_id: Option<String>,
79	    prompt: PromptRequest,
80	    router_config_override: Option<RouterConfigOverride>,
81	    expected_output_tokens: Option<u32>,
82	    priority_jump: f64,
83	    strict_priority: u32,
84	    policy_class: Option<String>,
85	    session_id: Option<String>,
86	    pinned_worker: Option<WorkerWithDpRank>,
87	    allowed_worker_ids: Option<HashSet<WorkerId>>,
88	    routing_constraints: RoutingConstraints,
89	}
90	
91	/// Resolved inputs for booking a reservation, shared by the cached and explicit
92	/// `create_reservation` paths.
93	struct ReservationBooking {
94	    key: RoutingPartitionId,
95	    selection_id: String,
96	    worker: WorkerWithDpRank,
97	    sequence_hashes: Vec<SequenceHash>,
98	    prefill_load_hint: Option<PrefillLoadHint>,
99	    expected_output_tokens: Option<u32>,
100	    track_prefill_tokens: bool,
101	    lora_name: Option<String>,
102	}
103	
104	#[derive(Debug, Clone)]
105	pub struct SelectionServiceConfig {
106	    pub port: u16,
107	    pub threads: usize,
108	    pub indexer_peers: Vec<String>,
109	    pub replica_sync_port: Option<u16>,
110	    pub replica_sync_peers: Vec<String>,
111	    pub kv_router_config: crate::config::KvRouterConfig,
112	    pub selection_cache: SelectionCacheConfig,
113	}
114	
115	pub struct SelectionCore {
116	    catalog: WorkerCatalog,
117	    entries: RwLock<HashMap<RoutingPartitionId, Arc<OnceCell<Arc<SelectionEntry>>>>>,
118	    indexer_registry: Arc<WorkerRegistry>,
119	    kv_router_config: crate::config::KvRouterConfig,
120	    worker_selection_policy_factory: Option<WorkerSelectionPolicyFactory>,
121	    worker_type: WorkerType,
122	    cancel_token: CancellationToken,
123	    replica_config: Option<ReplicaSyncConfig>,
124	    /// Booking inputs captured by `select`, keyed by `selection_id`, so a later
125	    /// `create_reservation` can replay them without re-sending the prompt.
126	    selection_cache: SelectionCache,
127	    tracking_hash: Arc<TrackingHashContext>,
128	}
129	
130	impl SelectionCore {
131	    fn entry(&self, key: &RoutingPartitionId) -> Option<Arc<SelectionEntry>> {
132	        self.entries
133	            .read()
134	            .get(key)
135	            .and_then(|entry| entry.get().cloned())
136	    }
137	
138	    fn initialized_entries(&self) -> Vec<Arc<SelectionEntry>> {
139	        self.entries
140	            .read()
141	            .values()
142	            .filter_map(|entry| entry.get().cloned())
143	            .collect()
144	    }
145	
146	    /// Create an intentionally local selector without replica synchronization
147	    /// or startup recovery.
148	    ///
149	    /// # Panics
150	    ///
151	    /// Panics when the tracking-hash configuration is invalid. Use
152	    /// [`Self::try_new_local`] when configuration errors must be reported.
153	    pub fn new_local(
154	        kv_router_config: crate::config::KvRouterConfig,
155	        indexer_threads: usize,
156	        cancel_token: CancellationToken,
157	        cache_config: SelectionCacheConfig,
158	    ) -> Self {
159	        Self::try_new_local(
160	            kv_router_config,
161	            indexer_threads,
162	            cancel_token,
163	            cache_config,
164	        )
165	        .expect("selection tracking hash configuration must be valid")
166	    }
167	
168	    /// Create a local selector and report invalid tracking configuration.
169	    pub fn try_new_local(
170	        kv_router_config: crate::config::KvRouterConfig,
171	        indexer_threads: usize,
172	        cancel_token: CancellationToken,
173	        cache_config: SelectionCacheConfig,
174	    ) -> anyhow::Result<Self> {
175	        kv_router_config
176	            .validate_config()
177	            .map_err(anyhow::Error::msg)?;
178	        let tracking_hash = Arc::new(TrackingHashContext::from_config(&kv_router_config)?);
179	        Ok(Self::new_inner(
180	            kv_router_config,
181	            indexer_threads,
182	            cancel_token,
183	            None,
184	            None,
185	            WorkerType::Aggregated,
186	            true,
187	            cache_config,
188	            tracking_hash,
189	        ))
190	    }
191	
192	    #[allow(clippy::too_many_arguments)]
193	    pub(super) fn new_inner(
194	        kv_router_config: crate::config::KvRouterConfig,
195	        indexer_threads: usize,
196	        cancel_token: CancellationToken,
197	        replica_config: Option<ReplicaSyncConfig>,
198	        worker_selection_policy_factory: Option<WorkerSelectionPolicyFactory>,
199	        worker_type: WorkerType,
200	        signal_indexer_ready: bool,
201	        cache_config: SelectionCacheConfig,
202	        tracking_hash: Arc<TrackingHashContext>,
203	    ) -> Self {
204	        let cancel_token = cancel_token.child_token();
205	        let indexer_registry = Arc::new(WorkerRegistry::new_with_cancel_token(
206	            indexer_threads,
207	            cancel_token.clone(),
208	        ));
209	        if signal_indexer_ready {
210	            indexer_registry.signal_ready();
211	        }
212	        Self {
213	            catalog: WorkerCatalog::default(),
214	            entries: RwLock::new(HashMap::new()),
215	            indexer_registry,
216	            kv_router_config,
217	            worker_selection_policy_factory,
218	            worker_type,
219	            cancel_token,
220	            replica_config,
221	            selection_cache: SelectionCache::new(&cache_config),
222	            tracking_hash,
223	        }
224	    }
225	
226	    /// Cancel core-scoped tasks (KV-event listeners, scheduling, replica sync,
227	    /// periodic expiry) without cancelling the parent token. In-flight and
228	    /// queued selections then fail fast.
229	    ///
230	    /// The KV indexer thread pool is owned by the registry and released when
231	    /// this `SelectionCore` is dropped. Idempotent.
232	    pub fn shutdown(&self) {
233	        self.cancel_token.cancel();
234	    }
235	
236	    fn ensure_running(&self) -> Result<(), SelectionError> {
237	        if self.cancel_token.is_cancelled() {
238	            return Err(SelectionError::NotReady(
239	                "selection service is shutting down".to_string(),
240	            ));
241	        }
242	        Ok(())
243	    }
244	
245	    pub(crate) async fn recover_indexer_from_peers(
246	        &self,
247	        peers: &[String],
248	    ) -> anyhow::Result<bool> {
249	        recovery::recover_from_peers(peers, &self.indexer_registry).await
250	    }
251	
252	    pub(crate) fn signal_indexer_ready(&self) {
253	        self.indexer_registry.signal_ready();
254	    }
255	
256	    pub(crate) async fn dump_indexer_events(&self) -> serde_json::Value {
257	        crate::services::indexer::server::dump_registry(&self.indexer_registry).await
258	    }
259	
260	    pub(crate) fn dispatch_replica_event(&self, envelope: ScopedReplicaEvent) {
261	        let (key, block_size, event) = envelope.into_parts();
262	        if self
263	            .replica_config
264	            .as_ref()
265	            .is_some_and(|config| config.is_self_event(&event))
266	        {
267	            return;
268	        }
269	
270	        let Some(entry) = self.entry(&key) else {
271	            tracing::trace!(%key, "Dropping replica event for unknown selector entry");
272	            return;
273	        };
274	        if entry.block_size != block_size {
275	            tracing::debug!(
276	                %key,
277	                expected_block_size = entry.block_size,
278	                received_block_size = block_size,
279	                "Dropping selector replica event with mismatched block size"
280	            );
281	            return;
282	        }
283	        let Some(replica_tx) = &entry.replica_tx else {
284	            return;
285	        };
286	        match replica_tx.try_send(event) {
287	            Ok(()) => {}
288	            Err(mpsc::error::TrySendError::Full(event)) => {
289	                tracing::trace!(
290	                    %key,
291	                    request_id = %event.request_id,
292	                    "Selector replica subscriber channel full; dropping event"
293	                );
294	            }
295	            Err(mpsc::error::TrySendError::Closed(_)) => {
296	                tracing::debug!(%key, "Selector replica subscriber channel closed");
297	            }
298	        }
299	    }
300	
301	    pub async fn upsert_worker(
302	        &self,
303	        req: WorkerRequest,
304	    ) -> Result<WorkerCatalogRecord, SelectionError> {
305	        self.ensure_running()?;
306	        let (previous, record) = self.catalog.upsert(req);
307	        self.reconcile_worker(record.worker_id, previous).await
308	    }
309	
310	    pub async fn patch_worker(
311	        &self,
312	        worker_id: WorkerId,
313	        patch: WorkerPatchRequest,
314	    ) -> Result<WorkerCatalogRecord, SelectionError> {
315	        self.ensure_running()?;
316	        let (previous, record) = self.catalog.patch(worker_id, patch)?;
317	        self.reconcile_worker(record.worker_id, Some(previous))
318	            .await
319	    }
320	
321	    pub async fn delete_worker(
322	        &self,
323	        worker_id: WorkerId,
324	    ) -> Result<WorkerCatalogRecord, SelectionError> {
325	        let Some(previous) = self.catalog.get(worker_id) else {
326	            return Err(SelectionError::NotFound(format!(
327	                "worker {worker_id} not found"
328	            )));
329	        };
330	        let key = previous.key();
331	        self.catalog
332	            .set_lifecycle(worker_id, WorkerLifecycle::Draining, Vec::new());
333	        self.publish_scheduler_config(&key)?;
334	        self.cleanup_indexer_registration(&previous).await;
335	        let record = self
336	            .catalog
337	            .set_lifecycle(worker_id, WorkerLifecycle::Unschedulable, Vec::new())
338	            .ok_or_else(|| SelectionError::NotFound(format!("worker {worker_id} not found")))?;
339	        self.publish_scheduler_config(&key)?;
340	        Ok(record)
341	    }
342	
343	    pub fn list_workers(
344	        &self,
345	        model_name: Option<&str>,
346	        routing_group: Option<&str>,
347	    ) -> Vec<WorkerCatalogRecord> {
348	        self.catalog.list(model_name, routing_group)
349	    }
