361	    async fn reconcile_worker(
362	        &self,
363	        worker_id: WorkerId,
364	        previous: Option<WorkerCatalogRecord>,
365	    ) -> Result<WorkerCatalogRecord, SelectionError> {
366	        let Some(record) = self.catalog.get(worker_id) else {
367	            return Err(SelectionError::NotFound(format!(
368	                "worker {worker_id} not found"
369	            )));
370	        };
371	
372	        if previous
373	            .as_ref()
374	            .is_some_and(|record| record.lifecycle == WorkerLifecycle::Schedulable)
375	        {
376	            self.catalog
377	                .set_lifecycle(worker_id, WorkerLifecycle::Draining, Vec::new());
378	            self.publish_scheduler_config(&previous.as_ref().expect("checked").key())?;
379	            self.cleanup_indexer_registration(previous.as_ref().expect("checked"))
380	                .await;
381	        }
382	
383	        let queueing_enabled = self
384	            .kv_router_config
385	            .queueing_enabled(Some(&record.model_name))
386	            .map_err(|error| SelectionError::BadRequest(error.to_string()))?;
387	        let reasons = record
388	            .missing_schedulable_metadata(queueing_enabled, self.kv_router_config.use_kv_events);
389	        if !reasons.is_empty() {
390	            let updated = self
391	                .catalog
392	                .set_lifecycle(worker_id, WorkerLifecycle::Incomplete, reasons)
393	                .ok_or_else(|| SelectionError::NotFound(format!("worker {worker_id} not found")))?;
394	            self.publish_scheduler_config(&updated.key())?;
395	            return Ok(updated);
396	        }
397	
398	        if let Err(error) = self.ensure_entry(&record) {
399	            return self.mark_incomplete_after_reconcile_error(worker_id, record.key(), error);
400	        }
401	        if self.kv_router_config.use_kv_events
402	            && let Err(error) = self.register_indexer_listeners(&record).await
403	        {
404	            self.cleanup_indexer_registration(&record).await;
405	            return self.mark_incomplete_after_reconcile_error(worker_id, record.key(), error);
406	        }
407	
408	        let updated = self
409	            .catalog
410	            .set_lifecycle(worker_id, WorkerLifecycle::Schedulable, Vec::new())
411	            .ok_or_else(|| SelectionError::NotFound(format!("worker {worker_id} not found")))?;
412	        self.publish_scheduler_config(&updated.key())?;
413	        Ok(updated)
414	    }
