416	    fn mark_incomplete_after_reconcile_error(
417	        &self,
418	        worker_id: WorkerId,
419	        key: RoutingPartitionId,
420	        error: SelectionError,
421	    ) -> Result<WorkerCatalogRecord, SelectionError> {
422	        let updated = self
423	            .catalog
424	            .set_lifecycle(
425	                worker_id,
426	                WorkerLifecycle::Incomplete,
427	                vec![format!("reconciliation failed: {error}")],
428	            )
429	            .ok_or_else(|| SelectionError::NotFound(format!("worker {worker_id} not found")))?;
430	        self.publish_scheduler_config(&key)?;
431	        Ok(updated)
432	    }
