434	    fn ensure_entry(
435	        &self,
436	        record: &WorkerCatalogRecord,
437	    ) -> Result<Arc<SelectionEntry>, SelectionError> {
438	        let block_size = record
439	            .block_size
440	            .ok_or_else(|| SelectionError::BadRequest("block_size is required".to_string()))?;
441	        let is_eagle = record.is_eagle.unwrap_or(false);
442	        let key = record.key();
443	
444	        let entry_cell = { self.entries.read().get(&key).cloned() };
445	        let entry_cell = entry_cell.unwrap_or_else(|| {
446	            self.entries
447	                .write()
448	                .entry(key.clone())
449	                .or_insert_with(|| Arc::new(OnceCell::new()))
450	                .clone()
451	        });
452	        let entry = entry_cell
453	            .get_or_try_init(|| -> Result<Arc<SelectionEntry>, SelectionError> {
454	                let (workers_tx, workers_rx) = watch::channel(HashMap::new());
455	                let scoped_replica_sync =
456	                    setup_scoped_replica_sync(self.replica_config.as_ref(), &key, block_size);
457	                let worker_label = self.worker_type.as_str();
458	                let slots = Arc::new(ActiveSequencesMultiWorker::new_with_replica_worker_policy(
459	                    scoped_replica_sync.publisher,
460	                    block_size as usize,
461	                    HashMap::new(),
462	                    scoped_replica_sync.enabled,
463	                    scoped_replica_sync.process_id,
464	                    worker_label,
465	                    ReplicaWorkerPolicy::RequireRegistered,
466	                ));
467	                let replica_tx = scoped_replica_sync.channel.map(|(replica_tx, subscriber)| {
468	                    slots.start_replica_sync(subscriber, self.cancel_token.child_token());
469	                    replica_tx
470	                });
471	                slots.start_periodic_force_expiry_across_all_workers(
472	                    self.cancel_token.child_token(),
473	                );
474	
475	                let indexer = self
476	                    .indexer_registry
477	                    .get_or_create_indexer(key.clone(), block_size);
478	                let overlap_refresh = Arc::new(TieredOverlapRefresher::new(
479	                    indexer.clone(),
480	                    self.kv_router_config.clone(),
481	                    block_size,
482	                ));
483	                let selector = self.worker_selection_policy_factory.as_ref().map_or_else(
484	                    || WorkerSelectionPolicy::default(self.kv_router_config.clone(), worker_label),
485	                    |factory| factory(&self.kv_router_config, self.worker_type, key.as_ref()),
486	                );
487	                let profile = self
488	                    .kv_router_config
489	                    .policy_profile(Some(&key.model_name))
490	                    .map_err(|error| SelectionError::BadRequest(error.to_string()))?;
491	                let scheduler = LocalScheduler::new_with_policy_profile(
492	                    slots,
493	                    workers_rx,
494	                    profile,
495	                    block_size,
496	                    selector,
497	                    None,
498	                    Some(overlap_refresh),
499	                    None,
500	                    // Standalone selection has no router Client snapshot.
501	                    None,
502	                    self.kv_router_config.router_queue_recheck_interval(),
503	                    self.kv_router_config.router_track_prefill_tokens,
504	                    self.cancel_token.child_token(),
505	                    worker_label,
506	                    true,
507	                )?;
508	                Ok(Arc::new(SelectionEntry {
509	                    key: key.clone(),
510	                    block_size,
511	                    is_eagle,
512	                    indexer,
513	                    workers_tx,
514	                    scheduler,
515	                    replica_tx,
516	                }))
517	            })?
518	            .clone();
519	        if entry.block_size != block_size {
520	            return Err(SelectionError::Conflict(format!(
521	                "block_size mismatch for {key}: existing={} requested={block_size}",
522	                entry.block_size
523	            )));
524	        }
525	        if entry.is_eagle != is_eagle {
526	            return Err(SelectionError::Conflict(format!(
527	                "is_eagle mismatch for {key}: existing={} requested={is_eagle}",
528	                entry.is_eagle
529	            )));
530	        }
531	        Ok(entry)
532	    }
