534	    async fn register_indexer_listeners(
535	        &self,
536	        record: &WorkerCatalogRecord,
537	    ) -> Result<(), SelectionError> {
538	        let block_size = record
539	            .block_size
540	            .ok_or_else(|| SelectionError::BadRequest("block_size is required".to_string()))?;
541	        let mut endpoints: Vec<_> = record.listener_endpoints().into_iter().collect();
542	        endpoints.sort_by_key(|(dp_rank, _)| *dp_rank);
543	        for (dp_rank, endpoint) in endpoints {
544	            crate::services::common::zmq::validate_endpoint(&endpoint).map_err(|error| {
545	                SelectionError::BadRequest(format!(
546	                    "invalid kv_events endpoint for worker {} dp_rank {dp_rank}: {error}",
547	                    record.worker_id
548	                ))
549	            })?;
550	            if let Some(replay_endpoint) = record.replay_endpoint.as_deref() {
551	                crate::services::common::zmq::validate_endpoint(replay_endpoint).map_err(
552	                    |error| {
553	                        SelectionError::BadRequest(format!(
554	                            "invalid replay endpoint for worker {} dp_rank {dp_rank}: {error}",
555	                            record.worker_id
556	                        ))
557	                    },
558	                )?;
559	            }
560	            self.indexer_registry
561	                .register(
562	                    record.worker_id,
563	                    endpoint,
564	                    dp_rank,
565	                    record.model_name.clone(),
566	                    record.routing_group.clone(),
567	                    block_size,
568	                    record.replay_endpoint.clone(),
569	                )
570	                .await
571	                .map_err(|error| SelectionError::BadRequest(error.to_string()))?;
572	        }
573	        Ok(())
574	    }
