576	    async fn cleanup_indexer_registration(&self, record: &WorkerCatalogRecord) {
577	        if self.kv_router_config.use_kv_events {
578	            if let Err(error) = self
579	                .indexer_registry
580	                .deregister(record.worker_id, &record.model_name, &record.routing_group)
581	                .await
582	            {
583	                tracing::debug!(
584	                    worker_id = record.worker_id,
585	                    error = %error,
586	                    "indexer deregistration skipped or failed"
587	                );
588	            }
589	            return;
590	        }
591	
592	        let key = record.key();
593	        let indexer = self
594	            .indexer_registry
595	            .get_indexer(&key)
596	            .map(|entry| entry.indexer.clone());
597	        if let Some(indexer) = indexer {
598	            indexer.remove_worker(record.worker_id).await;
599	        }
600	    }
