696	    async fn schedule_selection(
697	        &self,
698	        operation: SelectionOperation,
699	        book: bool,
700	    ) -> Result<SelectResponse, SelectionError> {
701	        let SelectionOperation {
702	            key,
703	            selection_id,
704	            prompt,
705	            router_config_override,
706	            expected_output_tokens,
707	            priority_jump,
708	            strict_priority,
709	            policy_class,
710	            session_id,
711	            pinned_worker,
712	            allowed_worker_ids,
713	            routing_constraints,
714	        } = operation;
715	        self.ensure_running()?;
716	
717	        let entry = self.ready_entry(&key)?;
718	        let PreparedSelectionInputs {
719	            block_hashes,
720	            sequence_hashes,
721	            isl_tokens,
722	            overlap,
723	        } = self
724	            .prepare_selection_inputs(
725	                &entry,
726	                &prompt,
727	                self.kv_router_config
728	                    .assume_kv_reuse(router_config_override.as_ref()),
729	            )
730	            .await?;
731	        let mode = if book {
732	            ScheduleMode::Tracked {
733	                request_id: selection_id.clone().ok_or_else(|| {
734	                    SelectionError::Internal(
735	                        "booked selection did not include a selection ID".to_string(),
736	                    )
737	                })?,
738	            }
739	        } else {
740	            ScheduleMode::QueryOnly {
741	                request_id: selection_id.clone(),
742	            }
743	        };
744	        let track_prefill_tokens = router_config_override
745	            .as_ref()
746	            .and_then(|cfg| cfg.track_prefill_tokens)
747	            .unwrap_or(self.kv_router_config.router_track_prefill_tokens);
748	        // `select` (book == false) with a selection_id caches the booking inputs
749	        // so a follow-up `create_reservation` can replay them by that id.
750	        let cached_inputs = (!book).then(|| selection_id.clone()).flatten().map(|id| {
751	            (
752	                id,
753	                sequence_hashes.clone(),
754	                prompt.lora_name.clone(),
755	                track_prefill_tokens,
756	            )
757	        });
758	        let response_sequence_hashes =
759	            book.then(|| sequence_hashes.iter().map(|hash| *hash as i64).collect());
760	        let response_isl_tokens = book.then_some(isl_tokens);
761	        let response_track_prefill_tokens = book.then_some(track_prefill_tokens);
762	        let schedule_request = ScheduleRequest {
763	            mode,
764	            token_seq: Some(sequence_hashes),
765	            block_hashes: Some(block_hashes),
766	            isl_tokens,
767	            overlap,
768	            router_hint_candidates: None,
769	            retain_router_hint_chain: false,
770	            router_config_override,
771	            lora_name: prompt.lora_name,
772	            priority_jump,
773	            strict_priority,
774	            policy_class,
775	            session_context: session_id
776	                .map(|session_id| SessionContext::new(session_id, None, None, None, None)),
777	            expected_output_tokens,
778	            pinned_worker,
779	            allowed_worker_ids,
780	            routing_constraints,
781	            shared_cache_hits: None,
782	        };
783	        let response = tokio::select! {
784	            biased;
785	            _ = self.cancel_token.cancelled() => {
786	                return Err(SelectionError::Scheduler(KvSchedulerError::SubscriberShutdown));
787	            }
788	            result = entry.scheduler.schedule_request(schedule_request) => result?,
789	        };
790	        let endpoint = self
791	            .catalog
792	            .schedulable_endpoint(response.best_worker.worker_id, &key)
793	            .ok_or_else(|| {
794	                SelectionError::Internal(format!(
795	                    "selected worker {} is no longer schedulable",
796	                    response.best_worker.worker_id
797	                ))
798	            })?;
799	        let overlap = MooncakeOverlapSummary::from_selected_worker_tiers(
800	            &response.selected_worker_tiers,
801	            entry.block_size,
802	        );
803	
804	        let effective_prefill = effective_prefill_tokens(isl_tokens, response.cached_tokens);
805	
806	        if let Some((cache_id, sequence_hashes, lora_name, track_prefill_tokens)) = cached_inputs {
807	            self.selection_cache.insert(
808	                cache_id,
809	                PendingSelection {
810	                    key: key.clone(),
811	                    worker: response.best_worker,
812	                    sequence_hashes,
813	                    isl_tokens,
814	                    effective_prefill_tokens: effective_prefill,
815	                    expected_output_tokens,
816	                    track_prefill_tokens,
817	                    lora_name,
818	                },
819	                Instant::now(),
820	            );
821	        }
822	
823	        Ok(SelectResponse {
824	            selection_id,
825	            sequence_hashes: response_sequence_hashes,
826	            isl_tokens: response_isl_tokens,
827	            track_prefill_tokens: response_track_prefill_tokens,
828	            model_name: key.model_name,
829	            routing_group: key.routing_group,
830	            worker_id: response.best_worker.worker_id,
831	            dp_rank: response.best_worker.dp_rank,
832	            endpoint,
833	            block_size: entry.block_size,
834	            overlap,
835	            effective_prefill_tokens: effective_prefill,
836	        })
837	    }
