839	    pub async fn create_reservation(
840	        &self,
841	        req: ReservationRequest,
842	    ) -> Result<ReservationResponse, SelectionError> {
843	        self.ensure_running()?;
844	
845	        let key = RoutingPartitionId::new(req.model_name.clone(), req.routing_group.clone());
846	
847	        // Explicit form: book on the given worker under selection_id, discarding
848	        // any cached selection for the id so a later replay can't book stale state.
849	        if let Some(worker_id) = req.worker_id {
850	            self.selection_cache.discard(&key, &req.selection_id);
851	            return self.reserve_explicit(key, worker_id, req).await;
852	        }
853	
854	        // Replay form: peek, book, and consume only once the booking lands. A
855	        // failure leaves the entry for a retry; concurrent replays of the same
856	        // id collide at the scheduler, so they can't double-book.
857	        let Some((pending, generation)) =
858	            self.selection_cache
859	                .peek(&key, &req.selection_id, Instant::now())
860	        else {
861	            return Err(SelectionError::NotFound(format!(
862	                "no pending selection {} for {key} (expired, already used, \
863	                 or never selected)",
864	                req.selection_id
865	            )));
866	        };
867	        let response = self.book_cached_selection(pending, &req).await?;
868	        self.selection_cache
869	            .remove(&key, &req.selection_id, generation);
870	        Ok(response)
871	    }
