873	    /// Book a reservation replaying what the matching `select` captured; request
874	    /// fields other than the ids are ignored.
875	    async fn book_cached_selection(
876	        &self,
877	        pending: Arc<PendingSelection>,
878	        req: &ReservationRequest,
879	    ) -> Result<ReservationResponse, SelectionError> {
880	        let (entry, endpoint, prefill_load_hint) = self.resolve_cached_booking(&pending)?;
881	        let track_prefill_tokens = pending.track_prefill_tokens;
882	        self.finalize_reservation(
883	            entry,
884	            endpoint,
885	            ReservationBooking {
886	                key: pending.key.clone(),
887	                selection_id: req.selection_id.clone(),
888	                worker: pending.worker,
889	                sequence_hashes: pending.sequence_hashes.clone(),
890	                prefill_load_hint: track_prefill_tokens.then_some(prefill_load_hint),
891	                expected_output_tokens: pending.expected_output_tokens,
892	                track_prefill_tokens,
893	                lora_name: pending.lora_name.clone(),
894	            },
895	        )
896	        .await
897	    }
