899	    /// Resolve everything a cached booking needs (ready entry, schedulable
900	    /// endpoint, prefill hint), so the only fallible step left in
901	    /// `finalize_reservation` is the scheduler call.
902	    fn resolve_cached_booking(
903	        &self,
904	        pending: &PendingSelection,
905	    ) -> Result<(Arc<SelectionEntry>, String, PrefillLoadHint), SelectionError> {
906	        let entry = self.ready_entry(&pending.key)?;
907	        // Validate the full worker/rank against current topology; a rank a PATCH
908	        // removed during the window is rejected (the entry stays for a retry).
909	        let endpoint = self
910	            .catalog
911	            .schedulable_worker_endpoint(pending.worker, &pending.key)
912	            .ok_or_else(|| {
913	                SelectionError::NotFound(format!(
914	                    "schedulable worker {} (dp_rank {}) not found for {}",
915	                    pending.worker.worker_id, pending.worker.dp_rank, pending.key
916	                ))
917	            })?;
918	        let prefill_load_hint = prefill_load_hint_from_effective_tokens(
919	            pending.isl_tokens,
920	            pending.effective_prefill_tokens,
921	        )
922	        .map_err(|error| SelectionError::BadRequest(error.to_string()))?;
923	        Ok((entry, endpoint, prefill_load_hint))
924	    }
