940	    /// Book a reservation from a self-contained request (explicit worker_id and prompt).
941	    async fn reserve_explicit(
942	        &self,
943	        key: RoutingPartitionId,
944	        worker_id: WorkerId,
945	        req: ReservationRequest,
946	    ) -> Result<ReservationResponse, SelectionError> {
947	        let entry = self.ready_entry(&key)?;
948	        let normalized = req.prompt.normalize_for_reservation(
949	            entry.is_eagle,
950	            TrackingHashInput {
951	                context: &self.tracking_hash,
952	                scope: tracking_scope(&entry),
953	                assume_kv_reuse: self
954	                    .kv_router_config
955	                    .assume_kv_reuse(req.router_config_override.as_ref()),
956	            },
957	        )?;
958	        let prefill_load_hint = req
959	            .effective_prefill_tokens
960	            .map(|tokens| {
961	                prefill_load_hint_from_effective_tokens(normalized.isl_tokens, tokens)
962	                    .map_err(|error| SelectionError::BadRequest(error.to_string()))
963	            })
964	            .transpose()?;
965	        let worker = WorkerWithDpRank::new(worker_id, req.dp_rank.unwrap_or(0));
966	        let endpoint = self.schedulable_endpoint(worker.worker_id, &key)?;
967	        let track_prefill_tokens = req.track_prefill_tokens.unwrap_or_else(|| {
968	            req.effective_prefill_tokens.is_some()
969	                || req
970	                    .router_config_override
971	                    .as_ref()
972	                    .and_then(|cfg| cfg.track_prefill_tokens)
973	                    .unwrap_or(self.kv_router_config.router_track_prefill_tokens)
974	        });
975	
976	        self.finalize_reservation(
977	            entry,
978	            endpoint,
979	            ReservationBooking {
980	                key,
981	                selection_id: req.selection_id,
982	                worker,
983	                sequence_hashes: normalized.sequence_hashes,
984	                prefill_load_hint,
985	                expected_output_tokens: req.expected_output_tokens,
986	                track_prefill_tokens,
987	                lora_name: req.prompt.lora_name,
988	            },
989	        )
990	        .await
991	    }
992	
993	    /// Register the booking with the scheduler. All fallible resolution happens
994	    /// in the caller; the scheduler add here is the last step that can fail, and
995	    /// the cached path leaves its selection in place (to retry) if it does.
996	    async fn finalize_reservation(
997	        &self,
998	        entry: Arc<SelectionEntry>,
999	        endpoint: String,
1000	        booking: ReservationBooking,
1001	    ) -> Result<ReservationResponse, SelectionError> {
1002	        let ReservationBooking {
1003	            key,
1004	            selection_id,
1005	            worker,
1006	            sequence_hashes,
1007	            prefill_load_hint,
1008	            expected_output_tokens,
1009	            track_prefill_tokens,
1010	            lora_name,
1011	        } = booking;
1012	
1013	        // Strict booking: never lazily recreate a worker/rank removed since the
1014	        // reservation was resolved.
1015	        entry
1016	            .scheduler
1017	            .add_request_if_registered(SequenceRequest {
1018	                request_id: selection_id.clone(),
1019	                token_sequence: Some(sequence_hashes),
1020	                track_prefill_tokens,
1021	                expected_output_tokens,
1022	                prefill_load_hint,
1023	                worker,
1024	                lora_name,
1025	            })
1026	            .await?;
1027	
1028	        Ok(ReservationResponse {
1029	            selection_id,
1030	            model_name: key.model_name,
1031	            routing_group: key.routing_group,
1032	            worker_id: worker.worker_id,
1033	            dp_rank: worker.dp_rank,
1034	            endpoint,
1035	        })
1036	    }
