1066	    pub fn add_output_block(
1067	        &self,
1068	        selection_id: &str,
1069	        decay_fraction: Option<f64>,
1070	    ) -> Result<(), SelectionError> {
1071	        if let Some(frac) = decay_fraction
1072	            && !(0.0..=1.0).contains(&frac)
1073	        {
1074	            return Err(SelectionError::BadRequest(
1075	                "decay_fraction must be between 0.0 and 1.0".to_string(),
1076	            ));
1077	        }
1078	
1079	        let entries = self.initialized_entries();
1080	        for entry in entries {
1081	            match entry
1082	                .scheduler
1083	                .add_output_block(selection_id, decay_fraction)
1084	            {
1085	                Ok(()) => return Ok(()),
1086	                Err(SequenceError::RequestNotFound { .. }) => continue,
1087	                Err(error) => return Err(error.into()),
1088	            }
1089	        }
1090	        Err(SelectionError::NotFound(format!(
1091	            "reservation {selection_id} not found"
1092	        )))
1093	    }
