1095	    pub fn loads(
1096	        &self,
1097	        model_name: Option<&str>,
1098	        routing_group: Option<&str>,
1099	    ) -> Vec<ModelLoadResponse> {
1100	        let entries = self.initialized_entries();
1101	        let mut loads = Vec::new();
1102	        for entry in entries {
1103	            if model_name.is_some_and(|model_name| entry.key.model_name != model_name)
1104	                || routing_group
1105	                    .is_some_and(|routing_group| entry.key.routing_group != routing_group)
1106	            {
1107	                continue;
1108	            }
1109	            loads.push(ModelLoadResponse {
1110	                model_name: entry.key.model_name.clone(),
1111	                routing_group: entry.key.routing_group.clone(),
1112	                loads: entry
1113	                    .scheduler
1114	                    .get_potential_loads(None, 0, HashMap::new(), false),
1115	                pending_count: entry.scheduler.pending_count(),
1116	                pending_isl_tokens: entry.scheduler.pending_isl_tokens(),
1117	            });
1118	        }
1119	        loads.sort_by(|a, b| {
1120	            (&a.model_name, &a.routing_group).cmp(&(&b.model_name, &b.routing_group))
1121	        });
1122	        loads
1123	    }
