1164	            .find_tiered_matches(block_hashes)
1165	            .await
1166	            .map_err(|error| SelectionError::Internal(error.to_string()))?;
1167	        let schedulable_workers = self.schedulable_worker_ranks(&key);
1168	        Ok(
1169	            OverlapAnalysis::new(&self.kv_router_config, entry.block_size, &tiered)
1170	                .scores_response(
1171	                    req.router_config_override.as_ref(),
1172	                    num_blocks,
1173	                    schedulable_workers,
1174	                    false,
1175	                    None,
1176	                    None,
1177	                ),
