1181	    async fn prepare_selection_inputs(
1182	        &self,
1183	        entry: &SelectionEntry,
1184	        prompt: &PromptRequest,
1185	        assume_kv_reuse: bool,
1186	    ) -> Result<PreparedSelectionInputs, SelectionError> {
1187	        let normalized = prompt.normalize_for_selection(
1188	            entry.is_eagle,
1189	            TrackingHashInput {
1190	                context: &self.tracking_hash,
1191	                scope: tracking_scope(entry),
1192	                assume_kv_reuse,
1193	            },
1194	        )?;
1195	        let tiered = if normalized.block_hashes.is_empty() {
1196	            TieredMatchDetails::default()
1197	        } else {
1198	            entry
1199	                .indexer
1200	                .find_tiered_matches(normalized.block_hashes.clone())
1201	                .await
1202	                .map_err(|error| SelectionError::Internal(error.to_string()))?
1203	        };
1204	        let overlap =
1205	            OverlapAnalysis::new(&self.kv_router_config, entry.block_size, &tiered).signals();
1206	        drop(tiered);
1207	        Ok(PreparedSelectionInputs {
1208	            block_hashes: normalized.block_hashes,
1209	            sequence_hashes: normalized.sequence_hashes,
1210	            isl_tokens: normalized.isl_tokens,
1211	            overlap,
1212	        })
1213	    }
