1215	    fn schedulable_worker_ranks(&self, key: &RoutingPartitionId) -> Vec<WorkerWithDpRank> {
1216	        let configs = self.catalog.scheduler_configs_for_key(key);
1217	        let mut workers = Vec::new();
1218	        for (worker_id, config) in configs {
1219	            let start = config.data_parallel_start_rank;
1220	            let end = start.saturating_add(config.data_parallel_size);
1221	            for dp_rank in start..end {
1222	                workers.push(WorkerWithDpRank::new(worker_id, dp_rank));
1223	            }
1224	        }
1225	        workers
1226	    }
1227	}
