4	//! Startup registration for statically linked worker-selection policies.
5	
6	use std::collections::HashMap;
7	use std::sync::Arc;
8	
9	use serde::de::DeserializeOwned;
10	use thiserror::Error;
11	
12	use crate::WorkerSelectionPolicyFactory;
13	use crate::WorkerType;
14	use crate::config::KvRouterConfig;
15	use crate::scheduling::config::WorkerSelectionPolicySelections;
16	pub use crate::scheduling::config::{
17	    DYN_ROUTER_DECODE_POLICY, DYN_ROUTER_PREFILL_POLICY, DYN_ROUTER_WORKER_SELECTION_POLICY,
18	};
19	use crate::scheduling::selector::WorkerSelectionPolicy;
20	
21	/// Parses one policy instance's YAML parameters and creates its partition factory.
22	pub type WorkerSelectionPolicyProvider = Arc<
23	    dyn Fn(
24	            &WorkerSelectionPolicyParameters,
25	        ) -> Result<WorkerSelectionPolicyFactory, WorkerSelectionPolicyProviderError>
26	        + Send
27	        + Sync,
28	>;
29	
30	/// YAML parameters passed to a linked worker-selection policy provider.
31	#[derive(Debug, Clone)]
32	pub struct WorkerSelectionPolicyParameters(serde_yaml::Value);
33	
34	impl WorkerSelectionPolicyParameters {
35	    fn new(value: serde_yaml::Value) -> Self {
36	        Self(value)
37	    }
38	
39	    /// Deserialize this policy instance's parameter mapping into a policy-owned type.
40	    pub fn deserialize<T: DeserializeOwned>(
41	        &self,
42	    ) -> Result<T, WorkerSelectionPolicyProviderError> {
43	        serde_yaml::from_value(self.0.clone())
44	            .map_err(|source| WorkerSelectionPolicyProviderError::new(source.to_string()))
45	    }
46	}
47	
48	/// A policy-owned validation failure while creating a parameterized policy factory.
49	#[derive(Debug, Error)]
50	#[error("{message}")]
51	pub struct WorkerSelectionPolicyProviderError {
52	    message: String,
53	}
54	
55	impl WorkerSelectionPolicyProviderError {
56	    /// Construct an error suitable for user-facing startup diagnostics.
57	    pub fn new(message: impl Into<String>) -> Self {
58	        Self {
59	            message: message.into(),
60	        }
61	    }
62	}
63	
64	/// A startup-only registry of policy types linked into a custom Dynamo image.
65	#[derive(Clone, Default)]
66	pub struct WorkerSelectionPolicyRegistry {
67	    providers: HashMap<String, WorkerSelectionPolicyProvider>,
68	}
69	
70	/// An error from policy registration or startup resolution.
71	#[derive(Debug, Error)]
72	pub enum WorkerSelectionPolicyRegistryError {
73	    #[error("worker-selection policy type must not be empty")]
74	    EmptyName,
75	    #[error("worker-selection policy type 'default' is reserved for Dynamo's built-in selector")]
76	    ReservedDefault,
77	    #[error("worker-selection policy type {name:?} is already registered")]
78	    Duplicate { name: String },
79	    #[error(transparent)]
80	    Selection(#[from] crate::scheduling::config::WorkerSelectionPolicyConfigError),
81	    #[error("unknown worker-selection instance {name:?}; configured instances: {available}")]
82	    UnknownInstance { name: String, available: String },
83	    #[error("unknown worker-selection policy type {name:?}; linked policy types: {available}")]
84	    UnknownType { name: String, available: String },
85	    #[error("invalid parameters for worker-selection policy type {policy_type:?}: {source}")]
86	    Provider {
87	        policy_type: String,
88	        #[source]
89	        source: WorkerSelectionPolicyProviderError,
90	    },
91	}
92	
93	impl WorkerSelectionPolicyRegistry {
94	    /// Whether this image has no linked custom worker-selection policy types.
95	    pub fn is_empty(&self) -> bool {
96	        self.providers.is_empty()
97	    }
98	
99	    /// Register a policy type supplied by a linked policy crate.
100	    pub fn register(
101	        &mut self,
102	        name: impl Into<String>,
103	        provider: WorkerSelectionPolicyProvider,
104	    ) -> Result<(), WorkerSelectionPolicyRegistryError> {
105	        let name = name.into();
106	        if name.is_empty() {
107	            return Err(WorkerSelectionPolicyRegistryError::EmptyName);
108	        }
109	        if name == "default" {
110	            return Err(WorkerSelectionPolicyRegistryError::ReservedDefault);
111	        }
112	        if self.providers.contains_key(&name) {
113	            return Err(WorkerSelectionPolicyRegistryError::Duplicate { name });
114	        }
115	        self.providers.insert(name, provider);
116	        Ok(())
117	    }
118	
119	    /// Resolve the configured policy instances once at process startup.
120	    ///
121	    /// Aggregated, prefill, decode, and encode pools can select separate instances. The returned
122	    /// factory dispatches by the typed role that the host supplies for each worker pool.
123	    pub fn resolve(
124	        &self,
125	        config: &KvRouterConfig,
126	    ) -> Result<Option<WorkerSelectionPolicyFactory>, WorkerSelectionPolicyRegistryError> {
127	        let selected = config.selected_worker_selection_policy_instances()?;
128	        let policy_config = config.worker_selection_config().map_err(|source| {
129	            crate::scheduling::config::WorkerSelectionPolicyConfigError::Config { source }
130	        })?;
131	        self.resolve_selections(policy_config, selected)
132	    }
133	
134	    /// Resolve only the policy selected for one worker role.
135	    ///
136	    /// Single-pool hosts use this method to avoid loading policy types for worker pools that they
137	    /// do not construct.
138	    pub fn resolve_for_worker_type(
139	        &self,
140	        config: &KvRouterConfig,
141	        worker_type: WorkerType,
142	    ) -> Result<Option<WorkerSelectionPolicyFactory>, WorkerSelectionPolicyRegistryError> {
143	        let selected = config.selected_worker_selection_policy_instance_for(worker_type)?;
144	        let policy_config = config.worker_selection_config().map_err(|source| {
145	            crate::scheduling::config::WorkerSelectionPolicyConfigError::Config { source }
146	        })?;
147	        self.resolve_selected(policy_config, selected.as_deref())
148	    }
149	
150	    fn resolve_selections(
151	        &self,
152	        policy_config: Option<&crate::scheduling::WorkerSelectionConfig>,
153	        selected: WorkerSelectionPolicySelections,
154	    ) -> Result<Option<WorkerSelectionPolicyFactory>, WorkerSelectionPolicyRegistryError> {
155	        let mut resolved = HashMap::new();
156	        let aggregated = self.resolve_selected_cached(
157	            policy_config,
158	            selected.aggregated.as_deref(),
159	            &mut resolved,
160	        )?;
161	        let prefill = self.resolve_selected_cached(
162	            policy_config,
163	            selected.prefill.as_deref(),
164	            &mut resolved,
165	        )?;
166	        let decode =
167	            self.resolve_selected_cached(policy_config, selected.decode.as_deref(), &mut resolved)?;
168	        let encode =
169	            self.resolve_selected_cached(policy_config, selected.encode.as_deref(), &mut resolved)?;
170	
171	        if aggregated.is_none() && prefill.is_none() && decode.is_none() && encode.is_none() {
172	            return Ok(None);
173	        }
174	
175	        Ok(Some(Arc::new(move |config, worker_type, partition| {
176	            let selected = match worker_type {
177	                WorkerType::Aggregated => aggregated.as_ref(),
178	                WorkerType::Prefill => prefill.as_ref(),
179	                WorkerType::Decode => decode.as_ref(),
180	                WorkerType::Encode => encode.as_ref(),
181	            };
182	            match selected {
183	                Some(factory) => factory(config, worker_type, partition),
184	                None => WorkerSelectionPolicy::default(
185	                    config.clone(),
186	                    worker_type.default_selector_label(),
187	                ),
188	            }
189	        })))
190	    }
191	
192	    fn resolve_selected_cached(
193	        &self,
194	        config: Option<&crate::scheduling::WorkerSelectionConfig>,
195	        selected: Option<&str>,
196	        resolved: &mut HashMap<String, WorkerSelectionPolicyFactory>,
197	    ) -> Result<Option<WorkerSelectionPolicyFactory>, WorkerSelectionPolicyRegistryError> {
198	        let Some(selected) = selected else {
199	            return Ok(None);
200	        };
201	        if let Some(factory) = resolved.get(selected) {
202	            return Ok(Some(factory.clone()));
203	        }
204	        let factory = self.resolve_selected(config, Some(selected))?;
205	        if let Some(factory) = factory {
206	            resolved.insert(selected.to_owned(), factory.clone());
207	            Ok(Some(factory))
208	        } else {
209	            Ok(None)
210	        }
211	    }
212	
213	    fn resolve_selected(
214	        &self,
215	        config: Option<&crate::scheduling::WorkerSelectionConfig>,
