97	    pub async fn build(self) -> anyhow::Result<SelectionService> {
98	        self.kv_router_config
99	            .validate_config()
100	            .map_err(anyhow::Error::msg)?;
101	        let worker_selection_policy_factory = self
102	            .worker_selection_policy_registry
103	            .resolve_for_worker_type(&self.kv_router_config, self.worker_type)?;
104	        let tracking_hash = Arc::new(TrackingHashContext::from_config(&self.kv_router_config)?);
105	        let cancel_token = CancellationToken::new();
106	        let mut startup_guard = StartupGuard::new(cancel_token.clone());
107	        let replica_runtime = setup_replica_sync(
108	            self.replica_sync_port,
109	            &self.replica_sync_peers,
110	            cancel_token.child_token(),
111	        )?;
112	        if replica_runtime.is_some() {
113	            tracing::info!(
114	                router_tracking_hash = %tracking_hash.algorithm(),
115	                router_tracking_key_id = ?tracking_hash.key_id(),
116	                "Selection replica synchronization initialized"
117	            );
118	        }
119	        let replica_config = replica_runtime.as_ref().map(ReplicaSyncRuntime::config);
120	        let core = Arc::new(SelectionCore::new_inner(
121	            self.kv_router_config,
122	            self.indexer_threads,
123	            cancel_token.clone(),
124	            replica_config,
125	            worker_selection_policy_factory,
126	            self.worker_type,
127	            false,
128	            self.selection_cache,
129	            tracking_hash,
130	        ));
131	
132	        if !self.indexer_peers.is_empty() {
133	            match core.recover_indexer_from_peers(&self.indexer_peers).await {
134	                Ok(true) => tracing::info!("Selection indexer recovery completed"),
135	                Ok(false) => {
136	                    tracing::warn!(
137	                        "No reachable selection indexer peers; starting with empty state"
138	                    )
139	                }
140	                Err(error) => {
141	                    tracing::warn!(%error, "Selection indexer recovery failed; starting with empty state")
142	                }
143	            }
144	        }
145	        core.signal_indexer_ready();
146	
147	        let peer_manager = if replica_runtime.is_some() {
148	            let weak_core = Arc::downgrade(&core);
149	            Some(PeerManager::start(
150	                self.replica_sync_peers,
151	                cancel_token.child_token(),
152	                move |event| {
153	                    if let Some(core) = weak_core.upgrade() {
154	                        core.dispatch_replica_event(event);
155	                    }
156	                },
157	            )?)
158	        } else {
159	            None
160	        };
161	
162	        startup_guard.disarm();
163	        Ok(SelectionService {
164	            core,
165	            peer_manager,
166	            replica_runtime,
167	            replica_sync_port: self.replica_sync_port,
168	            cancel_token,
169	        })
170	    }
171	}
