28	/// Low-level selector used by routing hosts.
29	///
30	/// External policies should use [`WorkerSelectionPolicy`].
31	pub trait WorkerSelector<C: WorkerConfigLike> {
32	    /// Optional worker data required by this selector.
33	    fn required_worker_inputs(&self) -> WorkerInputs;
34	
35	    fn select_worker(
36	        &self,
37	        input: WorkerSelectionInput<'_, C>,
38	    ) -> Result<WorkerSelectionResult, KvSchedulerError>;
