41	/// Inputs supplied by the selector's host.
42	#[derive(Clone, Copy)]
43	pub enum WorkerSelectionInput<'a, C: WorkerConfigLike> {
44	    Configured {
45	        workers: &'a HashMap<WorkerId, C>,
46	        request: &'a SchedulingRequest,
