64	
65	impl<'a, C: WorkerConfigLike> WorkerSelectionInput<'a, C> {
66	    pub fn configured(
67	        workers: &'a HashMap<WorkerId, C>,
68	        request: &'a SchedulingRequest,
69	        eligibility: RoutingEligibility<'a>,
70	        block_size: u32,
