119	#[derive(Debug, Clone, Copy)]
120	struct LogitWeights {
121	    overlap_score_credit: f64,
122	    overlap_score_credit_decay: f64,
123	    prefill_load_scale: f64,
124	    shared_cache_multiplier: f64,
125	}
126	
127	struct MaterializedSelectionInput<'a> {
128	    request: &'a SchedulingRequest,
129	    context: WorkerSelectionContext<'a>,
130	}
131	
132	impl<'a> MaterializedSelectionInput<'a> {
133	    fn new(request: &'a SchedulingRequest, block_size: u32, weights: LogitWeights) -> Self {
134	        Self {
135	            request,
136	            context: WorkerSelectionContext {
137	                request,
138	                request_id: request.mode.request_id().unwrap_or("-"),
139	                request_blocks: request.request_blocks(block_size),
140	                block_size,
141	                track_prefill_tokens: request.track_prefill_tokens,
142	                weights,
143	                router_temperature_override: request
144	                    .router_config_override
145	                    .as_ref()
146	                    .and_then(|config| config.router_temperature),
147	            },
148	        }
149	    }
150	
151	    fn row(
152	        &self,
153	        worker: WorkerWithDpRank,
154	        preferred_taint_multiplier: Option<f64>,
155	        inputs: WorkerInputs,
156	    ) -> WorkerCandidate {
157	        self.row_with_device_overlap(
158	            worker,
159	            preferred_taint_multiplier,
160	            inputs,
161	            |_, device_overlap_blocks| device_overlap_blocks,
162	        )
163	    }
164	
165	    fn row_with_device_overlap(
166	        &self,
167	        worker: WorkerWithDpRank,
168	        preferred_taint_multiplier: Option<f64>,
169	        inputs: WorkerInputs,
170	        select_device_overlap: impl FnOnce(f64, f64) -> f64,
171	    ) -> WorkerCandidate {
172	        let cached_tokens = if inputs.contains(WorkerInputs::CACHE)
173	            || (inputs.contains(WorkerInputs::LOAD) && self.request.track_prefill_tokens)
174	        {
175	            self.request.effective_cached_tokens_for(worker)
176	        } else {
177	            0
178	        };
179	        let worker_load = if inputs.contains(WorkerInputs::LOAD) {
180	            self.request.worker_loads.get(&worker).copied()
181	        } else {
182	            None
183	        };
184	        let cache = if inputs.contains(WorkerInputs::CACHE) {
185	            let effective_overlap_blocks = self.request.effective_overlap_blocks_for(worker);
186	            let reported_device_overlap_blocks = self
187	                .request
188	                .overlap
189	                .tier_overlap_blocks
190	                .device
191	                .get(&worker)
192	                .copied()
193	                .map(|blocks| blocks as f64)
194	                .unwrap_or(0.0);
195	            let device_overlap_blocks =
196	                select_device_overlap(effective_overlap_blocks, reported_device_overlap_blocks);
197	            let shared_beyond = |device_blocks: f64| {
198	                self.request.shared_cache_hits.as_ref().map_or(0, |hits| {
199	                    // `hits_beyond` expects the unweighted device prefix depth.
200	                    hits.hits_beyond(device_blocks.round().max(0.0) as u32)
201	                })
202	            };
203	            WorkerCacheInput {
204	                effective_overlap_blocks,
205	                device_overlap_blocks,
206	                host_overlap_blocks: self
207	                    .request
208	                    .overlap
209	                    .tier_overlap_blocks
210	                    .host_pinned
211	                    .get(&worker)
212	                    .copied()
213	                    .unwrap_or(0) as f64,
214	                disk_overlap_blocks: self
215	                    .request
216	                    .overlap
217	                    .tier_overlap_blocks
218	                    .disk
219	                    .get(&worker)
220	                    .copied()
221	                    .unwrap_or(0) as f64,
222	                shared_beyond_device_blocks: shared_beyond(device_overlap_blocks),
223	            }
224	        } else {
225	            WorkerCacheInput::default()
226	        };
227	        let load = if inputs.contains(WorkerInputs::LOAD) {
228	            let raw_prefill_tokens = if self.request.track_prefill_tokens {
229	                match worker_load {
230	                    Some(load) => {
231	                        // Preserve the legacy operation order when overlap exceeds the prompt.
232	                        let uncached_tokens = super::prefill_load::effective_prefill_tokens(
233	                            self.request.isl_tokens,
234	                            cached_tokens,
235	                        );
236	                        let projected_tokens = load.active_prefill_tokens + uncached_tokens;
237	                        projected_tokens.saturating_add(cached_tokens)
238	                    }
239	                    None => self.request.isl_tokens,
240	                }
241	            } else {
242	                0
243	            } as f64;
244	            let worker_load = worker_load.unwrap_or_default();
245	            WorkerLoadInput {
246	                raw_prefill_blocks: raw_prefill_tokens / self.context.block_size as f64,
247	                active_prefill_tokens: worker_load.active_prefill_tokens,
248	                decode_cost_blocks: worker_load.potential_decode_blocks() as f64,
249	                active_requests: worker_load.active_requests,
250	            }
251	        } else {
252	            WorkerLoadInput::default()
253	        };
254	
255	        WorkerCandidate {
256	            worker,
257	            inputs,
258	            cache,
259	            load,
260	            preferred_taint_multiplier,
261	        }
262	    }
263	}
