265	fn selection_result(
266	    request: &SchedulingRequest,
267	    worker: WorkerWithDpRank,
268	    block_size: u32,
269	) -> WorkerSelectionResult {
270	    WorkerSelectionResult {
271	        worker,
272	        required_blocks: request.request_blocks(block_size),
273	        effective_overlap_blocks: request.effective_overlap_blocks_for(worker),
274	        cached_tokens: request.effective_cached_tokens_for(worker),
275	        potential_decode_blocks: request
276	            .potential_decode_blocks_after_admission(worker, block_size),
277	    }
278	}
279	
280	fn log_selection<C: WorkerConfigLike>(
281	    workers: &HashMap<WorkerId, C>,
282	    request: &SchedulingRequest,
283	    worker: WorkerWithDpRank,
284	    worker_type: &'static str,
285	    cost: f64,
286	    effective_overlap_blocks: f64,
287	) {
288	    let request_id = request.mode.request_id().unwrap_or("-");
289	    let host_pinned_blocks = request
290	        .overlap
291	        .tier_overlap_blocks
292	        .host_pinned
293	        .get(&worker)
294	        .copied()
295	        .unwrap_or(0);
296	    let disk_blocks = request
297	        .overlap
298	        .tier_overlap_blocks
299	        .disk
300	        .get(&worker)
301	        .copied()
302	        .unwrap_or(0);
303	
304	    if request.pinned_worker == Some(worker) {
305	        tracing::info!(
306	            request_id,
307	            "Selected pinned worker: worker_type={}, worker_id={} dp_rank={:?}, logit: {:.3}, effective cached blocks: {:.2}",
308	            worker_type,
309	            worker.worker_id,
310	            worker.dp_rank,
311	            cost,
312	            effective_overlap_blocks,
313	        );
314	    } else if worker_type == "decode" {
315	        tracing::info!(
316	            router_mode = "kv",
317	            request_id,
318	            worker_id = worker.worker_id,
319	            worker_type = %worker_type,
320	            dp_rank = ?worker.dp_rank,
321	            logit = cost,
322	            host_pinned_blocks,
323	            disk_blocks,
324	            "Selected worker"
325	        );
326	    } else {
327	        let total_kv_blocks = workers
328	            .get(&worker.worker_id)
329	            .and_then(WorkerConfigLike::total_kv_blocks);
330	        tracing::info!(
331	            router_mode = "kv",
332	            request_id,
333	            worker_id = worker.worker_id,
334	            worker_type = %worker_type,
335	            dp_rank = ?worker.dp_rank,
336	            logit = cost,
337	            effective_cached_blocks = effective_overlap_blocks,
338	            host_pinned_blocks,
339	            disk_blocks,
340	            total_kv_blocks = ?total_kv_blocks,
341	            "Selected worker"
342	        );
343	    }
344	}
345	
346	#[inline(always)]
347	// DefaultWorkerSelector and SelectionService both converge here. Only the scorer/picker stage is
348	// dispatched; eligibility outcomes and result construction stay host-owned and shared.
349	fn select_worker_with_policy<C: WorkerConfigLike>(
350	    kv_router_config: &KvRouterConfig,
351	    worker_type: &'static str,
352	    state: WorkerSelectionPolicyStateRef<'_>,
353	    workers: &HashMap<WorkerId, C>,
354	    request: &SchedulingRequest,
355	    eligibility: RoutingEligibility<'_>,
356	    block_size: u32,
357	) -> Result<WorkerSelectionResult, KvSchedulerError> {
358	    assert!(request.isl_tokens > 0);
359	    eligibility.validate_pinned_worker_allowed()?;
360	
361	    if let Some(worker) = eligibility.pinned_worker() {
362	        match eligibility.validate_worker_rank(workers, worker) {
363	            Ok(_) => {}
364	            Err(WorkerEligibilityError::WorkerOverloaded { .. }) => {
365	                return Err(KvSchedulerError::PinnedWorkerOverloaded {
366	                    worker_id: worker.worker_id,
367	                });
368	            }
369	            Err(_) => return Err(KvSchedulerError::NoEndpoints),
370	        }
371	    }
372	
373	    let weights = selection_weights(kv_router_config, request);
374	    let input = MaterializedSelectionInput::new(request, block_size, weights);
375	    let selected = match state {
376	        WorkerSelectionPolicyStateRef::Default(picker) => {
377	            let scorer = DefaultWorkerScorer {
378	                kv_router_config,
379	                worker_type,
380	            };
381	            pick_default_worker(&scorer, picker, &input, workers, request, eligibility)
382	        }
383	        WorkerSelectionPolicyStateRef::Custom(state) => {
384	            let mut state = state.borrow_mut();
385	            let has_eligible_worker =
386	                collect_custom_candidates(&mut state, &input, workers, request, eligibility)?;
387	            let CustomWorkerSelectionState {
388	                picker,
389	                picker_inputs,
390	                candidates,
391	                cache_inputs,
392	                load_inputs,
393	                ..
394	            } = &mut *state;
395	            if candidates.is_empty() {
396	                if has_eligible_worker {
397	                    return Err(KvSchedulerError::AllEligibleWorkersFiltered);
398	                }
399	                None
400	            } else {
401	                debug_assert!(
402	                    !picker_inputs.contains(WorkerInputs::CACHE)
