383	    /// passes [`crate::WorkerType::as_str`].
384	    pub fn new_with_filters(
385	        kv_router_config: KvRouterConfig,
386	        worker_label: &'static str,
387	        filters: Vec<Box<dyn WorkerFilter>>,
388	        scorers: Vec<Box<dyn WorkerScorer>>,
389	        picker: Box<dyn WorkerPicker>,
390	    ) -> Self {
391	        let picker_inputs = picker.required_worker_inputs();
392	        let filter_inputs = filters.iter().fold(WorkerInputs::NONE, |inputs, filter| {
393	            inputs | filter.required_worker_inputs()
394	        });
395	        let scorer_picker_inputs = scorers.iter().fold(picker_inputs, |inputs, scorer| {
396	            inputs | scorer.required_worker_inputs()
397	        });
398	        Self {
399	            kv_router_config,
400	            worker_label,
401	            state: WorkerSelectionPolicyState::Custom(RefCell::new(CustomWorkerSelectionState {
402	                filters,
403	                scorers,
404	                picker,
405	                filter_inputs,
406	                scorer_picker_inputs,
407	                picker_inputs,
408	                candidates: Vec::new(),
409	                cache_inputs: Vec::new(),
410	                load_inputs: Vec::new(),
411	            })),
412	        }
413	    }
