416	    ///
417	    /// `worker_label` selects the built-in scoring and logging contract. Typed hosts use
418	    /// [`crate::WorkerType::default_selector_label`] to preserve Dynamo's historical behavior.
419	    pub fn default(kv_router_config: KvRouterConfig, worker_label: &'static str) -> Self {
420	        let picker = DefaultWorkerPicker::new(kv_router_config.router_temperature);
421	        Self {
422	            kv_router_config,
423	            worker_label,
424	            state: WorkerSelectionPolicyState::Default(picker),
425	        }
426	    }
427	}
