429	#[inline(always)]
430	#[allow(clippy::too_many_arguments)]
431	fn push_scored_candidate(
432	    context: &WorkerSelectionContext<'_>,
433	    candidate: &WorkerCandidate,
434	    scorers: &mut [Box<dyn WorkerScorer>],
435	    picker_inputs: WorkerInputs,
436	    candidates: &mut Vec<ScoredWorkerCandidate>,
437	    cache_inputs: &mut Vec<WorkerCacheInput>,
438	    load_inputs: &mut Vec<WorkerLoadInput>,
439	) -> Result<(), KvSchedulerError> {
440	    let mut cost = 0.0;
441	    for (scorer_index, scorer) in scorers.iter_mut().enumerate() {
442	        let contribution = scorer.score(context, candidate)?;
443	        cost += contribution;
444	        if !contribution.is_finite() || !cost.is_finite() {
445	            return Err(WorkerSelectionPolicyError::NonFiniteCost {
446	                scorer_index,
447	                row: candidates.len(),
448	            }
449	            .into());
450	        }
451	    }
452	    candidates.push(ScoredWorkerCandidate {
453	        worker: candidate.worker,
454	        cost,
455	        preferred_taint_multiplier: candidate.preferred_taint_multiplier,
456	    });
457	    if picker_inputs.contains(WorkerInputs::CACHE) {
458	        cache_inputs.push(candidate.cache);
459	    }
460	    if picker_inputs.contains(WorkerInputs::LOAD) {
461	        load_inputs.push(candidate.load);
462	    }
463	    Ok(())
464	}
