466	pub(super) fn collect_custom_candidates<C: WorkerConfigLike>(
467	    state: &mut CustomWorkerSelectionState,
468	    input: &MaterializedSelectionInput<'_>,
469	    workers: &HashMap<WorkerId, C>,
470	    request: &SchedulingRequest,
471	    eligibility: RoutingEligibility<'_>,
472	) -> Result<bool, KvSchedulerError> {
473	    let CustomWorkerSelectionState {
474	        filters,
475	        scorers,
476	        filter_inputs,
477	        scorer_picker_inputs,
478	        picker_inputs,
479	        candidates,
480	        cache_inputs,
481	        load_inputs,
482	        ..
483	    } = state;
484	    candidates.clear();
485	    cache_inputs.clear();
486	    load_inputs.clear();
487	    if filters.is_empty() {
488	        let materialize_preferred_taint = eligibility.pinned_worker().is_none()
489	            && scorer_picker_inputs.contains(WorkerInputs::PREFERRED_TAINT);
490	        let mut error = None;
491	        eligibility.any_eligible_worker_rank(workers, |worker, config| {
492	            let preferred_taint_multiplier = if materialize_preferred_taint {
493	                request
494	                    .routing_constraints
495	                    .preferred_taint_multiplier(config.taints())
496	            } else {
497	                None
498	            };
499	            let candidate = input.row(worker, preferred_taint_multiplier, *scorer_picker_inputs);
500	            if let Err(policy_error) = push_scored_candidate(
501	                &input.context,
502	                &candidate,
503	                scorers,
504	                *picker_inputs,
505	                candidates,
506	                cache_inputs,
507	                load_inputs,
508	            ) {
509	                error = Some(policy_error);
510	                return true;
511	            }
512	            false
513	        });
514	        if let Some(error) = error {
515	            return Err(error);
516	        }
517	        return Ok(!candidates.is_empty());
518	    }
519	
520	    let additional_inputs = scorer_picker_inputs.without(*filter_inputs);
521	    let materialize_filter_preferred_taint = eligibility.pinned_worker().is_none()
522	        && filter_inputs.contains(WorkerInputs::PREFERRED_TAINT);
523	    let materialize_additional_preferred_taint = eligibility.pinned_worker().is_none()
524	        && additional_inputs.contains(WorkerInputs::PREFERRED_TAINT);
525	    let mut has_eligible_worker = false;
526	    let mut error = None;
527	    eligibility.any_eligible_worker_rank(workers, |worker, config| {
528	        has_eligible_worker = true;
529	        let filter_preferred_taint_multiplier = if materialize_filter_preferred_taint {
530	            request
531	                .routing_constraints
532	                .preferred_taint_multiplier(config.taints())
533	        } else {
534	            None
535	        };
536	        let filter_candidate = input.row(worker, filter_preferred_taint_multiplier, *filter_inputs);
537	        for filter in filters.iter_mut() {
538	            match filter.keep(&input.context, &filter_candidate) {
539	                Ok(true) => {}
540	                Ok(false) => return false,
541	                Err(policy_error) => {
542	                    error = Some(policy_error.into());
543	                    return true;
544	                }
545	            }
546	        }
547	
548	        let additional_preferred_taint_multiplier = if materialize_additional_preferred_taint {
549	            request
550	                .routing_constraints
551	                .preferred_taint_multiplier(config.taints())
552	        } else {
553	            None
554	        };
555	        let additional = input.row(
556	            worker,
557	            additional_preferred_taint_multiplier,
558	            additional_inputs,
559	        );
560	        let candidate = filter_candidate.with_inputs_from(&additional, *scorer_picker_inputs);

